(()=>{'use strict';
let data=null,loading=null;
const URL='ffws-br-2026-s2/home-results.json?v=20260902-home-v24';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const shortTeam=name=>({
  'LOUD SNICKERS':'LOUD','FLUXO W7M':'FX','RISE GAMING':'RISE','RUSH GAMING':'RUSH',
  'TEAM SOLID':'TS','AFROGAMES':'AFG','CIVIS':'CTZ','LOOPS':'LPS','SX TET':'SX','CPT VOX':'CPT','ALPHA7':'A7',
  'INFLUENCE RAGE':'INF','FURY UNITED':'FURY','AXS FUSION':'AXS','HAWK GAMING':'HAWK'
}[String(name||'').toUpperCase()]||String(name||''));
const fmt=n=>Number(n||0).toLocaleString('pt-BR');
const slug=(v,sep='')=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,sep).replace(new RegExp(`^${sep||'\\s'}+|${sep||'\\s'}+$`,'g'),'');
const teamThumb=team=>`home-assets/teams/${slug(team,'-')}.webp`;
const playerThumb=name=>`home-assets/players/${slug(name)}.webp`;
const playerFull=name=>`player-photos/s2/${slug(name)}.webp`;
function playerImg(name){const s=slug(name);return `<img class="home-rank-avatar" src="${esc(playerThumb(name))}" alt="" loading="lazy" decoding="async" width="32" height="32" onerror="if(this.dataset.fb){this.onerror=null;this.src='silhueta.webp'}else{this.dataset.fb='1';this.src='${esc(playerFull(name))}'}">`}
function teamImg(team){return `<img class="home-rank-team-logo" src="${esc(teamThumb(team))}" alt="" loading="lazy" decoding="async" width="30" height="30" onerror="this.onerror=null;this.src='escudo.webp'">`}
async function load(){if(data)return data;if(loading)return loading;loading=fetch(URL,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject(new Error('HTTP '+r.status))).then(v=>data=v).catch(()=>data={teams:[],players:[],rankings:{kills:[],damage:[],assists:[]},weeklySelection:null,status:'upcoming'}).finally(()=>loading=null);return loading}
function placeholder(text,cols=5){return `<tr><td colspan="${cols}" class="home-rank-placeholder">${esc(text)}</td></tr>`}
function teamRows(rows){return rows.length?rows.slice(0,6).map((r,i)=>`<tr><td class="home-rank-pos">${i+1}</td><td class="home-rank-media"><a href="equipe.html?time=${encodeURIComponent(r.team)}" aria-label="${esc(shortTeam(r.team))}">${teamImg(r.team)}</a></td><td class="home-rank-main"><a class="home-rank-identity" href="equipe.html?time=${encodeURIComponent(r.team)}"><span><b>${esc(shortTeam(r.team))}</b><small>${Number(r.matches||0)} Q</small></span></a></td><td class="home-rank-number home-rank-points">${fmt(r.points)}</td><td class="home-rank-number">${fmt(r.kills)}</td></tr>`).join(''):placeholder('Classificação disponível após as primeiras quedas.')}
function playerRows(rows,metric){return rows.length?rows.slice(0,6).map((r,i)=>{const name=r.player||r.name||'';const href=`jogador.html?jogador=${encodeURIComponent(name)}&time=${encodeURIComponent(r.team||'')}`;return `<tr><td class="home-rank-pos">${i+1}</td><td class="home-rank-media"><a href="${href}" aria-label="${esc(name)}">${playerImg(name)}</a></td><td class="home-rank-main"><a class="home-rank-identity" href="${href}"><span><b>${esc(name)}</b><small>${esc(shortTeam(r.team||''))}</small></span></a></td><td class="home-rank-number">${fmt(r[metric])}</td><td class="home-rank-number home-rank-matches">${Number(r.matches||0)}</td></tr>`}).join(''):placeholder('Ranking disponível após as primeiras quedas.')}
function renderWeekly(selection){const root=document.getElementById('home-weekly-selection-list'),meta=document.getElementById('home-weekly-selection-meta');if(!root)return;const rows=Array.isArray(selection?.players)?selection.players:[];if(meta){const days=Array.isArray(selection?.days)?selection.days:[];meta.textContent=rows.length?`SEMANA ${selection.week||''}${days.length?` • DIAS ${days.join(' E ')}`:''}`:'EM BREVE'}if(!rows.length){root.innerHTML='<div class="home-weekly-empty">Seleção disponível após as rodadas da semana.</div>';return}root.innerHTML=rows.slice(0,4).map((r,i)=>{const name=r.player||r.name||'';return `<a class="home-weekly-player" href="jogador.html?jogador=${encodeURIComponent(name)}&time=${encodeURIComponent(r.team||'')}">${playerImg(name)}<span class="home-weekly-player-name"><b>${esc(name)}</b><small>${esc(shortTeam(r.team||''))} • ${esc(r.roleShort||'')}</small></span><span class="home-weekly-stat"><small>K</small><b>${fmt(r.kills)}</b></span><span class="home-weekly-stat home-weekly-dmg"><small>DMG</small><b>${fmt(r.damage)}</b></span></a>`}).join('')}
function renderRows(payload){const rankings=payload.rankings||{};const kills=rankings.kills||payload.players||[];[['home-tbody-teams',teamRows(payload.teams||[])],['home-tbody-players',playerRows(kills,'kills')],['home-tbody-damage',playerRows(rankings.damage||[],'damage')],['home-tbody-assists',playerRows(rankings.assists||[],'assists')]].forEach(([id,html])=>{const el=document.getElementById(id);if(el)el.innerHTML=html});renderWeekly(payload.weeklySelection)}
window.cffHomeRenderFinalStats=function(){renderRows(data||{teams:[],players:[],rankings:{},weeklySelection:null});load().then(renderRows);return true};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>load().then(renderRows),{once:true});else load().then(renderRows);
})();
